param([string]$In, [string]$OutDir)
$slides = @(14, 16, 18, 19, 20)
$ppt = New-Object -ComObject PowerPoint.Application
try {
  $p = $ppt.Presentations.Open($In, $true, $false, $false)
  foreach ($n in $slides) {
    $sl = $p.Slides.Item($n)
    for ($i = $sl.Shapes.Count; $i -ge 1; $i--) {
      $sh = $sl.Shapes.Item($i)
      if ($sh.HasTextFrame -and $sh.TextFrame.HasText) {
        $t = $sh.TextFrame.TextRange.Text
        if ($t.StartsWith('Figure:')) { $sh.Delete() }
      }
    }
    $sl.Export("$OutDir\slide$n.png", "PNG", 4000, 2250)
  }
  $p.Close()
} finally {
  $ppt.Quit()
}
"exported"

